import { update } from './app/store.js';
import { ETH_UNIT } from './app/sacrifices.js';
import { CONTRACTS, ETH_DIVISOR } from './app/chain-config.js';
import { __setSacrificePanelDepsForTest } from './components/app-sacrifice-panel.js';

// Raw chain wei for a display-ETH amount (testnet contracts are rescaled by ETH_DIVISOR).
const eth = (milli) => (BigInt(milli) * ETH_UNIT) / 1000n / BigInt(ETH_DIVISOR);
const wallet = '0x1111111111111111111111111111111111111111';
let snapshot;
let history;
let state = 'ready';
__setSacrificePanelDepsForTest({
  read: async () => state === 'offline' ? null : structuredClone(snapshot),
  history: async () => structuredClone(history),
});

function reset() {
  document.querySelector('#sacrifice-demo-host').replaceChildren();
  state = document.querySelector('#sacrifice-demo-state').value;
  update('connected.address', state === 'disconnected' ? null : wallet);
  update('ui.chainOk', true);
  update('ui.mode', 'self');
  snapshot = {
    day: 142, awardDay: 143, menuReady: state !== 'waiting', ended: state === 'ended',
    multiplierUnits: state === 'disconnected' ? null : 1600, score: 400,
    pools: [
      { key: 'vault', totalWageredWei: eth(1240), totalWeight: 198_400n, entryCount: 18, awardedMask: 0, slots: [3, 9, 6] },
      { key: 'sdgnrs', totalWageredWei: eth(830), totalWeight: 132_800n, entryCount: 11, awardedMask: 0, slots: [40, 24, 43] },
    ],
  };
  if (state === 'empty') snapshot.pools.forEach((pool) => { pool.totalWageredWei = 0n; pool.totalWeight = 0n; pool.entryCount = 0; });
  history = { available: true, awards: [], entries: state === 'entered'
    ? [{ issuer: CONTRACTS.VAULT, player: wallet, day: 142, amount: String(eth(100)), weight: '16000', entryIndex: 3 }]
    : [] };
  document.querySelector('#sacrifice-demo-host').append(document.createElement('app-sacrifice-panel'));
}
document.querySelector('#sacrifice-demo-state').addEventListener('change', reset);
reset();
